import{_ as l,a0 as p,w as d,s as u,I as i,x as t,a1 as o,A as n,ao as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const b=JSON.parse('{"title":"用系統日誌瞭解你的 Linux 系統 | LCTT x X-CMD","titleTemplate":false,"description":"用系統日誌瞭解你的 Linux 系統 | LCTT (201712) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"用系統日誌瞭解你的 Linux 系統 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"用系統日誌瞭解你的 Linux 系統 | LCTT (201712) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201712/20171117 System Logs Understand Your Linux System","title":"用系統日誌瞭解你的 Linux 系統","tag":"201712","desc":""},"relativePath":"201712/20171117 System Logs Understand Your Linux System.md","filePath":"[post].md"}'),r={name:"201712/20171117 System Logs Understand Your Linux System.md"};function m(g,e,x,L,f,c){const s=p("Link");return d(),u("div",null,[e[16]||(e[16]=i("h1",{id:"用系統日誌瞭解你的-linux-系統",tabindex:"-1"},[t("用系統日誌瞭解你的 Linux 系統 "),i("a",{class:"header-anchor",href:"#用系統日誌瞭解你的-linux-系統","aria-label":"Permalink to “用系統日誌瞭解你的 Linux 系統”"},"​")],-1)),i("p",null,[e[2]||(e[2]=t("本文摘自為 Linux 小白（或者非資深桌面用户）傳授技巧的系列文章。該系列文章旨在為 LinuxMagazine 發佈的第 30 期特別版 “",-1)),o(s,{href:"http://www.linux-magazine.com/Resources/Special-Editions/30-Getting-Started-with-Linux"},{default:n(()=>[...e[0]||(e[0]=[t("Linux 入門",-1)])]),_:1}),e[3]||(e[3]=t("” （基於 ",-1)),o(s,{href:"https://en.opensuse.org/Portal:42.3"},{default:n(()=>[...e[1]||(e[1]=[t("openSUSE Leap",-1)])]),_:1}),e[4]||(e[4]=t(" ）提供補充説明。",-1))]),e[17]||(e[17]=a('<p>本文作者是 Romeo S.，她是一名基於 PDX 的企業 Linux 專家，專注於為創新企業提供富有伸縮性的解決方案。</p><p>Linux 系統日誌非常重要。後台運行的程序（通常被稱為守護進程或者服務進程）處理了你 Linux 系統中的大部分任務。當這些守護進程工作時，它們將任務的詳細信息記錄進日誌文件中，作為它們做過什麼的“歷史”信息。這些守護進程的工作內容涵蓋從使用原子鐘同步時鐘到管理網絡連接。所有這些都被記錄進日誌文件，這樣當有錯誤發生時，你可以通過查閲特定的日誌文件來看出發生了什麼。</p><p><img src="https://www.suse.com/communities/blog/files/2017/11/markus-spiske-153537-300x450.jpg" alt=""></p><p><em>Photo by Markus Spiske on Unsplash</em></p><p>在你的 Linux 計算機上有很多不同的日誌。歷史上，它們一般以純文本的格式存儲到 <code>/var/log</code> 目錄中。現在依然有很多日誌這樣做，你可以很方便的使用 <code>less</code> 來查看它們。</p><p>在新裝的 openSUSE Leap 42.3 以及大多數現代操作系統上，重要的日誌由 <code>systemd</code> 初始化系統存儲。 <code>systemd</code>這套系統負責啓動守護進程，並在系統啓動時讓計算機做好被使用的準備。由 <code>systemd</code> 記錄的日誌以二進制格式存儲，這使得它們消耗的空間更小，更容易被瀏覽，也更容易被導出成其他各種格式，不過壞處就是你必須使用特定的工具才能查看。好在這個工具已經預安裝在你的系統上了：它的名字叫 <code>journalctl</code>，而且默認情況下，它會將每個守護進程的所有日誌都記錄到一個地方。</p><p>只需要運行 <code>journalctl</code> 命令就能查看你的 <code>systemd</code> 日誌了。它會用 <code>less</code> 分頁器顯示各種日誌。為了讓你有個直觀的感受, 下面是 <code>journalctl</code> 中摘錄的一條日誌記錄：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Jul 06 11:53:47 aaathats3as pulseaudio[2216]: [pulseaudio] alsa-util.c: Disabling timer-based scheduling because running inside a VM.</span></span></code></pre></div><p>這條獨立的日誌記錄以此包含了記錄的日期和時間、計算機名、記錄日誌的進程名、記錄日誌的進程 PID，以及日誌內容本身。</p><p>若系統中某個程序運行出問題了，則可以查看日誌文件並搜索（使用 <code>/</code> 加上要搜索的關鍵字）程序名稱。有可能導致該程序出問題的錯誤會記錄到系統日誌中。 有時，錯誤信息會足夠詳細到讓你能夠修復該問題。其他時候，你需要在 Web 上搜索解決方案。 Google 就很適合來搜索奇怪的 Linux 問題。不過搜索時請注意你只輸入了日誌的實際內容，行首的那些信息（日期、主機名、進程 ID) 對搜索來説是無意義的，會干擾搜索結果。</p><p>解決方法一般在搜索結果的前幾個連接中就會有了。當然，你不能只是無腦得運行從互聯網上找到的那些命令：請一定先搞清楚你要做的事情是什麼，它的效果會是什麼。據説，搜索系統日誌中的特定條目要比直接描述該故障通用關鍵字要有用的多。因為程序出錯有很多原因，而且同樣的故障表現也可能由多種問題引發的。</p><p>比如，系統無法發聲的原因有很多，可能是播放器沒有插好，也可能是聲音系統出故障了，還可能是缺少合適的驅動程序。如果你只是泛泛的描述故障表現，你會找到很多無關的解決方法，而你也會浪費大量的時間。而專門搜索日誌文件中的實際內容，你也許會查詢出其它人也有相同日誌內容的結果。</p><p>你可以對比一下圖 1 和圖 2。</p><p><img src="https://www.suse.com/communities/blog/files/2017/11/picture1-450x450.png" alt=""></p><p>圖 1 搜索系統的故障表現只會顯示泛泛的，不精確的結果。這種搜索通常沒什麼用。</p><p><img src="https://www.suse.com/communities/blog/files/2017/11/picture2-450x450.png" alt=""></p><p>圖 2 搜索特定的日誌行會顯示出精確的，有用的結果。這種搜索通常很有用。</p><p>也有一些系統不用 <code>journalctl</code> 來記錄日誌。在桌面系統中最常見的這類日誌包括用於記錄 openSUSE 包管理器的行為的 <code>/var/log/zypper.log</code>； 記錄系統啓動時消息的 <code>/var/log/boot.log</code> ，開機時這類消息往往滾動的特別快，根本看不過來；<code>/var/log/ntp</code> 用來記錄 Network Time Protocol （NTP）守護進程同步時間時發生的錯誤。 另一個存放硬件故障信息的地方是 “Kernel Ring Buffer”（內核環狀緩衝區），你可以輸入 <code>demesg -H</code> 命令來查看（這條命令也會調用 <code>less</code> 分頁器來查看）。“Kernel Ring Buffer” 存儲在內存中，因此會在重啓電腦後丟失。不過它包含了 Linux 內核中的重要事件，比如新增了硬件、加載了模組，以及奇怪的網絡錯誤.</p><p>希望你已經準備好深入瞭解你的 Linux 系統了! 祝你玩的開心!</p><hr>',20)),i("p",null,[e[6]||(e[6]=t("via: ",-1)),o(s,{href:"https://www.suse.com/communities/blog/system-logs-understand-linux-system/"},{default:n(()=>[...e[5]||(e[5]=[t("https://www.suse.com/communities/blog/system-logs-understand-linux-system/",-1)])]),_:1})]),i("p",null,[e[9]||(e[9]=t("作者：[chabowski] 譯者：",-1)),o(s,{href:"https://github.com/lujun9972"},{default:n(()=>[...e[7]||(e[7]=[t("lujun9972",-1)])]),_:1}),e[10]||(e[10]=t(" 校對：",-1)),o(s,{href:"https://github.com/wxy"},{default:n(()=>[...e[8]||(e[8]=[t("wxy",-1)])]),_:1})]),i("p",null,[e[13]||(e[13]=t("本文由 ",-1)),o(s,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...e[11]||(e[11]=[t("LCTT",-1)])]),_:1}),e[14]||(e[14]=t(" 原創編譯，",-1)),o(s,{href:"https://linux.cn/"},{default:n(()=>[...e[12]||(e[12]=[t("Linux中國",-1)])]),_:1}),e[15]||(e[15]=t(" 榮譽推出",-1))])])}const y=l(r,[["render",m]]);export{b as __pageData,y as default};
